#!/usr/bin/env python3
r"""My Classes laid out like Plans; Anytime at the bottom; the plan's "Friends can see · Plan A without …" line gone.
Tate, 2026-10-11, with a screenshot of a plan's day list: "i like how this is for plans do the same thing for my
classes"; with My Classes' week: "and bring back the anytime classes at the bottom what happened to that"; with the
plan's "Friends can see · Plan A without BUS 3392" row: "dont need this take away".
  · My Classes (this term's chip, and the term you're in / another term): the week, then a card per day — time, code,
    name, professor, seats (and Waitlist #n), friends' faces — like Plans, instead of a card per class.
  · Every class with no set weekday time (online, time not posted, weekend-only, no section yet) is in an Anytime card
    at the bottom — the term you're in had dropped classes with no meeting time from the cards entirely.
  · Plans: the row under the week (Friends can see / Only you, and how B or C differs from A) is gone. Who sees each
    plan is still Settings › Who sees your plans.
Usage: python3 my-classes-agenda-2026-10-11.py <repo-dir>   (replayable)"""
import sys, os
PA = os.path.join(sys.argv[1], 'app', 'index.html'); S = open(PA, encoding='utf-8').read()
def rep(a, b, label):
    global S
    if S.count(a) != 1: sys.exit(f'{label}: anchor matched {S.count(a)}x')
    S = S.replace(a, b)
rep('  return `${ts.secs.length ? `<div class="card" style="margin:10px 12px 0;padding:14px 0 12px">${grid(ts.secs, { sel: S.schedDay, act: \'schedDay\', blockAct: \'openClass\', H: 330, noNow: true })}</div>` : \'\'}\n  ${Object.keys(byCode).map(code => { const ss = byCode[code]; return `<button class="card ccard" style="margin:12px 12px 0;width:calc(100% - 24px)" data-a="openClass" data-x="${code}"${isNowT ? \' data-y="now"\' : \'\'}>\n   <div class="row sb"><span class="code">${code}</span>${ss[0].sec ? `<span class="muted b" style="font-size:13px">${esc(secLabel(ss[0].sec))}</span>` : \'\'}</div>\n   <div class="ctitle" style="margin:8px 0 4px">${esc(name(code))}</div>\n   ${ss.map(x => `<div class="muted b" style="font-size:14px">${esc(profName(x.prof))} · ${secWhen(x)}</div>`).join(\'\')}</button>`; }).join(\'\')}\n  ${ts.unplaced.map(code => `<button class="card ccard" style="margin:12px 12px 0;width:calc(100% - 24px)" data-a="openClass" data-x="${code}"${isNowT ? \' data-y="now"\' : \'\'}><div class="row sb"><span class="code">${code}</span><span class="muted b" style="font-size:13px">${(box.rows || []).some(r => canonCode(r.code) === code) ? \'No set time\' : \'No section yet\'}</span></div><div class="ctitle" style="margin:8px 0 0">${esc(name(code))}</div></button>`).join(\'\')}`;', "  return mineAgenda(ts.secs, ts.unplaced, { now: isNowT, other: !isNowT, label: tm.label, grid: { sel: S.schedDay, act: 'schedDay', blockAct: 'openClass', H: 330, noNow: true } });", 'other term')
rep('  ${secs.length ? `<div class="card" style="margin:10px 12px 0;padding:14px 0 12px">${grid(secs, { sel: S.schedDay, act: \'schedDay\', blockAct: \'secSheet\', H: 330, faces: true })}</div>` : \'\'}\n  ${Object.keys(byCode).map(code => { const ss = byCode[code], c = course(code), fr = TC.friends.filter(f => personSecs(f).some(x => ss.some(s => s.id === x.id))); return `<button class="card ccard" style="margin:12px 12px 0;width:calc(100% - 24px)" data-a="openClass" data-x="${code}">\n   <div class="row sb"><span class="code">${code}</span>${ss[0].sec ? `<span class="muted b" style="font-size:13px">${esc(secLabel(ss[0].sec))}</span>` : \'\'}</div>\n   <div class="ctitle" style="margin:8px 0 4px">${esc(c.title)}</div>\n   ${ss.map(s => `<div class="muted b" style="font-size:14px">${esc(profName(s.prof))} · ${secWhen(s)}${s.mineWl ? ` · <span style="color:var(--amber-ink);font-weight:900">Waitlist${s.wlPos ? \' #\' + esc(String(s.wlPos)) : \'\'}</span>` : \'\'}</div>`).join(\'\')}\n   ${fr.length ? `<div class="row" style="gap:8px;margin-top:10px">${avStack(fr, 24)}<span class="b" style="font-size:13px;color:var(--ink3)">${fr.map(f => esc(PEOPLE[f].short)).slice(0, 3).join(\', \')} in your section</span></div>` : \'\'}</button>`; }).join(\'\')}\n  ${unplaced.map(code => `<button class="card ccard" style="margin:12px 12px 0;width:calc(100% - 24px)" data-a="openClass" data-x="${code}"><div class="row sb"><span class="code">${code}</span><span class="muted b" style="font-size:13px">No section yet</span></div><div class="ctitle" style="margin:8px 0 0">${esc(course(code).title)}</div></button>`).join(\'\')}`;', "  ${secs.length || unplaced.length ? mineAgenda(secs, unplaced, { label: CFG.TERM_LABEL, grid: { sel: S.schedDay, act: 'schedDay', blockAct: 'secSheet', H: 330, faces: true } }) : ''}`;", 'my classes')
rep('  <div class="regbar under"><span class="regbadge" style="background:var(--bg);color:var(--muted)">${TC.planShared[S.plan] !== false ? \'Friends can see\' : \'Only you\'}</span>${planDiffLine(S.plan) ? `<span class="pl-diff">${esc(planDiffLine(S.plan))}</span>` : \'\'}</div>\n', '', 'plan row')
rep("/* What Schedule's top-right Share sends", '/* (2026-10-11) My Classes laid out like Plans (Tate: "i like how this is for plans do the same thing for my classes"):\n   the week, each day\'s classes in time order (time · code · name · professor · seats, friends\' faces), then the\n   classes with no set weekday time in an Anytime card at the bottom (Tate: "bring back the anytime classes at the\n   bottom"). o.now: the term you\'re in (its class pages); o.other: another term\'s read-only rows. */\nconst onWeekSec = s => !s.async && s.s != null && s.e != null && [...String(s.days || \'\')].some(d => DAYS.includes(d));\nfunction mineAgenda(secs, unplaced, o) {\n  const timed = secs.filter(onWeekSec), any = secs.filter(s => !onWeekSec(s));\n  const days = DAYS.map(d => [d, timed.filter(s => String(s.days).includes(d)).sort((a, b) => a.s - b.s)]).filter(x => x[1].length);\n  const act = s => o.now || o.other ? `data-a="openClass" data-x="${esc(s.code)}"${o.now ? \' data-y="now"\' : \'\'}` : `data-a="secSheet" data-x="${esc(s.code)}" data-y="${esc(s.id)}"`;\n  const frIn = s => o.other ? [] : TC.friends.filter(f => (o.now ? nowSecs(f) : personSecs(f)).some(x => String(x.id) === String(s.id)));\n  const seat = s => s.offFeed || !s.status || s.status === \'unknown\' ? \'\' : \' · \' + secSeatText(s);\n  const wl = s => s.mineWl ? ` · <span style="color:var(--amber-ink);font-weight:900">Waitlist${s.wlPos ? \' #\' + esc(String(s.wlPos)) : \'\'}</span>` : \'\';\n  const row = s => `<button class="arow" ${act(s)}><span class="tm">${hs(s.s)}<small>${hs(s.e)}</small></span><span class="vb"></span><span class="grow"><span style="font-weight:900;font-size:16px">${esc(s.code)}</span>${courseName(s.code) ? `<span class="cn">${esc(courseName(s.code))}</span>` : \'\'}<span class="muted b" style="display:block;font-size:14px">${esc(profName(s.prof))}${seat(s)}${wl(s)}</span></span>${avStack(frIn(s), 26)}</button>`;\n  const agenda = days.map(([d, list]) => `<div class="card agenda mine-ag"><h4>${DAYL[d]}${d === CLOCK.day && !o.other ? \'<span class="today">Today</span>\' : \'\'}</h4>${list.map(row).join(\'\')}</div>`).join(\'\');\n  const anyItems = any.map(s => `<button class="any-c" ${act(s)} aria-label="${esc(s.code)}">${anyCodeHtml(s.code)}</button>`)\n    .concat((unplaced || []).filter(c => !secs.some(s => s.code === c)).map(c => `<button class="any-c" data-a="openClass" data-x="${esc(c)}"${o.now ? \' data-y="now"\' : \'\'} aria-label="${esc(c)}">${anyCodeHtml(c)}</button>`));\n  const anyCard = anyItems.length ? `<div class="card anytime mine-any" role="group" aria-label="${esc(o.label)}: classes with no set time"><span style="font-weight:900;font-size:16px;margin-right:4px">Anytime</span>${anyItems.join(\'\')}</div>` : \'\';\n  const week = timed.length ? `<div class="card" style="margin:10px 12px 0;padding:14px 0 12px">${grid(timed, o.grid)}</div>` : \'\';\n  return week + agenda + anyCard;\n}\n/* What Schedule\'s top-right Share sends', 'helper')
open(PA, 'w', encoding='utf-8').write(S); print('my-classes-agenda: done')
